if("undefined"!=typeof ThemeSwitcher)console.log("\uD83D\uDD04 ThemeSwitcher j\xe1 carregado - ignorando duplicata");else{class e{constructor(){this.themeButtons=document.querySelectorAll(".theme-btn"),this.currentTheme=this.getSavedTheme()||"light",this.init()}init(){this.setTheme(this.currentTheme),this.setupEventListeners(),this.setupSystemPreferenceListener(),console.log("✅ SISTEMA DE TEMAS INICIALIZADO")}setupEventListeners(){this.themeButtons.forEach(e=>{e.addEventListener("click",e=>{let t=e.currentTarget.dataset.theme;this.setTheme(t),console.log(`🎨 Tema alterado para: ${t}`)})})}setTheme(e){document.documentElement.removeAttribute("data-theme"),document.documentElement.setAttribute("data-theme",e),this.updateButtonStates(e),this.saveTheme(e),this.currentTheme=e,console.log(`🎯 Tema aplicado: ${e}`)}updateButtonStates(e){this.themeButtons.forEach(t=>{let i=t.dataset.theme===e;t.setAttribute("aria-pressed",i),console.log(`🔘 Bot\xe3o ${t.dataset.theme}: ${i?"ativo":"inativo"}`)})}getSavedTheme(){return localStorage.getItem("preferred-theme")}saveTheme(e){localStorage.setItem("preferred-theme",e),console.log(`💾 Tema salvo: ${e}`)}setupSystemPreferenceListener(){let e=window.matchMedia("(prefers-color-scheme: dark)");e.addEventListener("change",e=>{if(!this.getSavedTheme()){let t=e.matches?"dark":"light";this.setTheme(t),console.log(`🖥️  Tema do sistema alterado para: ${t}`)}})}}window.ThemeSwitcher=e}const initializeThemeSwitcher=()=>{if(window.themeSwitcherInstance)return console.log("\uD83D\uDD04 ThemeSwitcher j\xe1 inicializado - ignorando duplicata"),!0;let e=document.querySelectorAll(".theme-btn");return e.length>0&&(console.log("\uD83D\uDE80 INICIALIZANDO SISTEMA DE CONTROLE DE TEMAS"),window.themeSwitcherInstance=new ThemeSwitcher,!0)};if("loading"===document.readyState)document.addEventListener("DOMContentLoaded",function(){setTimeout(()=>{let e=document.querySelectorAll(".theme-btn");e.length>0?(initializeThemeSwitcher(),console.log("✅ ThemeSwitcher inicializado na p\xe1gina atual")):console.log("ℹ️  ThemeSwitcher n\xe3o requerido nesta p\xe1gina")},300)});else{let t=document.querySelectorAll(".theme-btn");t.length>0?(initializeThemeSwitcher(),console.log("✅ ThemeSwitcher inicializado em p\xe1gina carregada")):console.log("ℹ️  ThemeSwitcher n\xe3o requerido nesta p\xe1gina")}window.addEventListener("hashchange",()=>{setTimeout(()=>{let e=document.querySelectorAll(".theme-btn");e.length>0&&!window.themeSwitcherInstance&&(console.log("\uD83D\uDD04 Inicializando ThemeSwitcher na nova rota SPA"),initializeThemeSwitcher())},200)});